css:
.header, .footer {
      text-align: center;
      margin-bottom: 20px;
    }
    .header h1 {
      margin-bottom:35px;
      font-size: 18px;
      text-transform: uppercase;
    }
    .header .info {
      width:100%;
      display: flex;
      margin-top: 10px;
    }

    .header>.info>div{
        width:50%;
        text-align: left;
    }

    .header>.info>div>div{
        margin-bottom:10px;
    }

    .header .info
    .section {
      margin-bottom: 20px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 10px;
      color:black;
    }
    table th, table td {
      border: 1px solid black;
      padding: 8px;
      text-align: left;
      font-size: 14px;
    }
    table th {
      background-color: #ccc;
    }
    .footer-table {
      margin-top:50px;
      width: 100%;
      border: 1px solid black;
      border-collapse: collapse;
    }
    .footer-table td {
      border: 1px solid black;
      text-align: center;
      height: 50px;
      vertical-align: top;
      font-size: 14px;
    }
    .signature-column{
        height: 100px;
    }
